// Original generated material scans, downsampled to 256px JPEG. No reference pixels.
import * as THREE from 'three';
const DATA = {
  pinboard: 'data:image/jpeg;base64,',
  street: 'data:image/jpeg;base64,',
  parquet: 'data:image/jpeg;base64,',
  brick: 'data:image/jpeg;base64,',
  concrete: 'data:image/jpeg;base64,',
  plaster: 'data:image/jpeg;base64,',
  wood: 'data:image/jpeg;base64,',
  fabric: 'data:image/jpeg;base64,',
};
export function ycMaterials() {

 return Object.fromEntries(Object.entries(DATA).map(([key, uri]) => {
  const canvas = document.createElement('canvas'); canvas.width = canvas.height = 512;
  const g = canvas.getContext('2d'); g.fillStyle = '#c5bfb2'; g.fillRect(0,0,512,512);
  const t = new THREE.CanvasTexture(canvas);
  t.userData.copies = [];
  const image = new Image(); image.onload = () => {
    if(key==='parquet'){
      // Worn, waxed boards: soft edges and gentle contrast. Drawn nine times so the softening wraps round the tile.
      g.filter='blur(.6px)';for(const ox of [-512,0,512])for(const oy of [-512,0,512])g.drawImage(image,ox,oy,512,512);g.filter='none';
      const pixels=g.getImageData(0,0,512,512),d=pixels.data;
      for(let i=0;i<d.length;i+=4){
        const r=Math.min(255,d[i]*1.28+18),gr=Math.min(255,d[i+1]*1.48+29),b=Math.min(255,d[i+2]*1.45+32);
        d[i]=215+(r-215)*.93;d[i+1]=155+(gr-155)*.93;d[i+2]=74+(b-74)*.93;   // a little under the scan's own contrast, around the boards' colour
      }
      g.putImageData(pixels,0,0);
    } else g.drawImage(image,0,0,512,512);
    if(key==='brick'){
      // Limewashed brick: uneven pigment, recessed mortar and worn plaster flecks.
      let seed=7921;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
      g.fillStyle='#7b7062';g.fillRect(0,0,512,512);
      for(let row=0;row<16;row++)for(let col=-1;col<8;col++){
        const v=132+Math.floor(rnd()*92),x=col*78+(row%2)*39,y=row*32,worn=rnd();
        // Most bricks keep their limewash; some have lost it and show the fired clay, a few are soot-dark.
        g.fillStyle=worn>.9?`rgb(${150+v*.12},${98+v*.08},${72+v*.06})`:worn<.06?`rgb(${v*.62},${v*.56},${v*.5})`:`rgb(${v+12},${v+3},${v-13})`;g.fillRect(x,y+2,75,28);
        g.fillStyle='#f3e3c333';g.fillRect(x+1,y+3,73,2);
        g.fillStyle='#62564535';g.fillRect(x+1,y+27,74,2);
        for(let k=0;k<35;k++){
          g.fillStyle=k%2?'rgba(75,62,43,.10)':'rgba(255,239,202,.12)';
          g.fillRect(x+rnd()*74,y+4+rnd()*23,3+rnd()*12,1+rnd()*4);
        }
      }
      for(let k=0;k<12000;k++){g.fillStyle=k%2?'#302c2510':'#fff0cf16';g.fillRect(rnd()*512,rnd()*512,1+rnd()*3,1);}

    }
    t.needsUpdate = true; for(const copy of t.userData.copies) copy.needsUpdate = true; }; image.src = uri;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.magFilter = THREE.LinearFilter; t.minFilter = THREE.LinearMipmapLinearFilter;
  return [key, t];
 }));
}

// Small authored detail maps: wear is in the diffuse image, not a modern shader.
export function ycDetail(kind) {
 const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');
 let seed=419;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
 g.fillStyle=kind==='leaf'?'#69834a':kind==='wood'?'#b59b72':'#c3c1b8';g.fillRect(0,0,256,256);
 for(let i=0;i<6000;i++){g.fillStyle=`rgba(${i%2?'255,248,229':'25,23,20'},${rand()*.13})`;g.fillRect(rand()*256,rand()*256,kind==='metal'?12:2,1);}
 if(kind==='wood'||kind==='ceiling'){
  for(let y=0;y<256;y+=32){g.fillStyle='#4f423244';g.fillRect(0,y,256,2);for(let k=0;k<22;k++){g.strokeStyle='#49372120';g.beginPath();g.moveTo(0,y+rand()*32);g.bezierCurveTo(60,y+rand()*32,170,y+rand()*32,256,y+rand()*32);g.stroke();}}
  if(kind==='wood')for(let i=0;i<7;i++){g.strokeStyle='#4c322a55';g.lineWidth=2;g.beginPath();g.arc(rand()*230+13,rand()*230+13,7+rand()*6,0,6.28);g.stroke();}
  if(kind==='ceiling')for(let row=0;row<8;row++){
    const offset=[0,97,41,180,23,139,211,66][row];
    // Each board, and each length of it, has its own tone.
    for(const [x0,x1] of [[0,offset],[offset,256]]){g.fillStyle=`rgba(${rand()<.5?'60,44,26':'255,240,214'},${.1+rand()*.24})`;g.fillRect(x0,row*32+2,x1-x0,30);}
    g.fillStyle='#4c3d2b66';g.fillRect(offset,row*32,2,32);
    for(const x of [offset+6,(offset+249)%256]){g.fillStyle='#51422f77';g.fillRect(x,row*32+8,1.5,1.5);g.fillRect(x,row*32+23,1.5,1.5);}
  }
 } else if(kind==='cabinet'||kind==='stretcher'){
  g.fillStyle='#b99768';g.fillRect(0,0,256,256);
  for(let y=0;y<256;y++){
    const v=105+rand()*105;
    g.strokeStyle=`rgb(${v+28},${v+4},${v-30})`;
    g.beginPath();g.moveTo(0,y);g.bezierCurveTo(70,y+Math.sin(y*.12)*4,170,y-3,256,y);g.stroke();
  }
  for(let i=0;i<24;i++){g.fillStyle=i%2?'#e2c28e55':'#4a301f55';g.fillRect(rand()*240,rand()*256,10+rand()*50,1+rand()*3);}
  if(kind==='cabinet'){
    g.strokeStyle='#513d2b';g.lineWidth=4;g.strokeRect(6,8,244,240);
    g.strokeStyle='#e0bd87';g.lineWidth=2;g.strokeRect(14,16,228,224);
    g.fillStyle='#332e25';g.fillRect(170,33,51,6);
  }
 } else if(kind==='metal'){
  g.strokeStyle='#4b4c4b';g.strokeRect(2,2,252,252);for(const x of [9,247])for(const y of [9,247]){g.fillStyle='#434540';g.beginPath();g.arc(x,y,3,0,6.28);g.fill();}
 } else if(kind==='keyboard'){
  g.fillStyle='#393c3b';for(let y=25;y<150;y+=22)for(let x=13;x<245;x+=23)g.fillRect(x,y,18,15);g.strokeStyle='#676b67';g.strokeRect(78,177,100,58);
 } else if(kind==='carton'){
  g.strokeStyle='#75664b';g.lineWidth=3;g.strokeRect(9,9,238,238);g.fillStyle='#866444';g.font='bold 26px Arial';g.textAlign='center';g.fillText('PIZZA',128,112);g.font='15px Arial';g.fillText('SLICE / SHARE / BUILD',128,140);g.fillRect(12,210,232,4);
 } else if(kind==='cup'){
  g.fillStyle='#a56c43';g.fillRect(0,84,256,100);g.fillStyle='#eee4ca';g.font='bold 27px Arial';g.fillText('COFFEE',68,145);g.fillStyle='#6c5745';g.fillRect(0,10,256,5);
 } else if(kind==='leaf'){
  g.strokeStyle='#b5c382';g.lineWidth=3;g.beginPath();g.moveTo(128,256);g.lineTo(128,0);g.stroke();g.lineWidth=1;for(let y=30;y<240;y+=25){g.beginPath();g.moveTo(30,y-20);g.lineTo(128,y+20);g.lineTo(226,y-20);g.stroke();}
 } else if(kind==='book'){
  g.fillStyle='#3e575b';g.fillRect(0,0,256,256);g.fillStyle='#e4d9bb';g.font='bold 24px Arial';g.textAlign='center';g.fillText('FIELD',128,70);g.fillText('NOTES',128,100);g.fillRect(20,200,216,4);g.font='17px Arial';g.fillText('BUILD',128,230);
 }
 // Broad baked bounce fades across each ceiling bay; its perimeter stays dark.
 if(kind==='ceiling'){
  const shade=g.createRadialGradient(128,128,30,128,128,180);
  shade.addColorStop(0,'rgba(0,0,0,0)');shade.addColorStop(1,'rgba(0,0,0,.16)');
  g.fillStyle=shade;g.fillRect(0,0,256,256);
 }
 const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;t.userData.copies=[];return t;
}
